const i=[{id:"meditation-M01",title:"Goyal et al. · 2014 · Meditation programs for psychological stress and well-being",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"47 randomized trials involving 3,515 adults with clinical conditions or stress found modest average anxiety, depression and pain benefits. Programs included at least four hours of teacher-present training.",limitation:"These were taught programs, not brief ODA practices. No superiority over active treatments was established; that does not prove equivalence. Several outcomes had insufficient evidence."},{id:"meditation-M03",title:"NCCIH · Meditation and mindfulness: effectiveness and safety",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Public guidance cautions against replacing conventional care or delaying assessment. Research on harms is limited; brain images alone do not establish practical health benefits.",limitation:"Guidance is not a trial of ODA. Shortening practice, opening eyes or choosing outward anchors cannot guarantee safety."},{id:"meditation-M04",title:"Farias et al. · 2020 · Adverse events in meditation practices and therapies",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"83 heterogeneous studies involving 6,703 participants reported adverse experiences. Pooled prevalence was 8.3%, with substantially different estimates in experimental and observational studies.",limitation:"Definitions and ascertainment varied. This is not an individual risk estimate for a brief app session, and reported events were not all established as caused by meditation."},{id:"meditation-M05",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests involving 8,461 participants found an average goal-attainment benefit from plans linking a recognizable situation with a specific response.",limitation:"Goals and designs varied, mostly with university students. This does not establish a benefit for ODA’s routine, an optimal meditation dose or a calm state."},{id:"meditation-M06",title:"Gan, Zhang & Chen · 2022 · Effects of body scan meditation",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 independent randomized-trial articles found a small mindfulness difference versus passive controls: g=.268, 95% CI .032 to .504. Standalone health evidence remains uncertain.",limitation:"Quality was low and heterogeneity high. The abstract does not verify total participants or health-effect estimates. It establishes neither universal ineffectiveness nor brief-scan health benefits."},{id:"meditation-M07",title:"Fischer, Messner & Pollatos · 2017 · Interoceptive processes after body scanning",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2017.00452/full",type:"research",finding:"An eight-week, twenty-minute daily body-scan protocol did not significantly outperform an audiobook on heartbeat counting in Study 1. Study 2 favored scanning over an inactive control.",limitation:"Small student samples and comparator-sensitive results. Heartbeat counting does not diagnose disease, explain numbness or validate ODA’s abbreviated contact exercise."},{id:"meditation-M08",title:"Hasenkamp et al. · 2012 · Mind wandering during focused meditation",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Fourteen experienced meditators marked wandering during breath-focused MRI practice. Researchers modeled wandering, awareness, shifting attention and sustained focus.",limitation:"Small exploratory imaging study, not a beginner intervention. It does not establish brain improvement, health benefits or effects of sound, contact or task-transfer adaptations."},{id:"meditation-M09",title:"Zeng et al. · 2015 · Loving-kindness and positive emotions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 empirical reports involved 1,759 people. Eight randomized waitlist comparisons found a modest average daily positive-emotion benefit. Pooled g=.395 or .392 used alternative measurements from one trial.",limitation:"Those estimates are sensitivity variants, not separate energetic and calm effects. Few active comparisons; no guaranteed kindness, relationship improvement or personality change. The bias-percentage denominator is unverified."},{id:"meditation-M11",title:"Fredrickson et al. · 2008 · Loving-kindness workshop and personal resources",url:"https://d1ftyfwtsv9bor.cloudfront.net/cbrt-readings/mod-6/fredrickson-open-hearts-build-lives-2008.pdf",type:"research",finding:"The program used six instructor-led sessions over seven weeks plus home recordings. A condition-by-week positive-emotion effect was significant among 139 completers.",limitation:"The same effect was nonsignificant in intent-to-treat and per-protocol analyses. Exclusions and waitlist comparison limit inference. Brief wishes are not this workshop or evidence of behavioral transfer."},{id:"meditation-M12",title:"Álvarez-Pérez et al. · 2022 · Mantra-based meditation review",url:"https://doi.org/10.3390/ijerph19063380",type:"research",finding:"51 studies covered varied mantra methods. The anxiety analysis included 25 studies and 1,825 people; its average estimate favored intervention, with a prediction interval including no benefit.",limitation:"No study had overall low bias risk. This does not validate Benson’s exact method or ODA’s short word anchor, establish superiority, or make paid training necessary."},{id:"meditation-M13",title:"Toth et al. · 2020 · Mental practice and performance",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"The university abstract reports 37 task and skill studies and a small publication-bias-adjusted performance association, r=.131.",limitation:"Full methods, total participants, confidence interval, 115-effects count and older comparison were not verified. This does not establish personality change, healing or the efficacy of ODA’s rehearsal-and-action combination."},{id:"meditation-M14",title:"Lally et al. · 2010 · Habit formation in everyday life",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 volunteers tracked eating, drinking or activity behaviors for 84 days. Among 39 acceptable models, time to 95% of modeled automaticity varied substantially.",limitation:"Observational modeling, partly extrapolated beyond follow-up. Neither 21 nor 66 days is a deadline; this was not meditation. The nonrandomized omission analysis cannot guarantee consequences of future missed practice."},{id:"meditation-M15",title:"Simonsson et al. · 2026 · Adverse experiences in brief meditation",url:"https://mental.jmir.org/2026/1/e95628/",type:"research",finding:"5,049 US and UK adults were randomized to brief practices or usual internet use. No detectable excess distress appeared for meditation versus internet use: OR 1.05, 95% CI .76 to 1.47.",limitation:"Distress still occurred. Overall 4.1% includes all groups, not meditation only. This secondary analysis does not prove identical risk, repeated-session safety or a meditation-specific duration effect."},{id:"meditation-M16",title:"Harvard Health · 2011 · Benson’s relaxation response",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Practitioner guidance describes comfortable quiet sitting, repeating an acceptable word, sound, phrase or prayer, and returning when thoughts intrude. The recommendation was ten to twenty minutes daily.",limitation:"Blog and anecdote, not an efficacy trial. Complete feet-to-face and exhale instructions, required one-week word use, secular/religious equivalence and a tested short version were not verified."},{id:"meditation-M17",title:"Plum Village · Walking meditation",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Traditional guidance attends to foot contact and ordinary breathing. Step coordination is optional and follows a comfortable rhythm; attention can include surroundings.",limitation:"Practice guidance, not an isolated efficacy trial or optimal dose. Keep eyes open and hazards first. Seated and shorter ODA alternatives are adaptations."},{id:"meditation-M18",title:"Sharon Salzberg · Lovingkindness book page",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"The author page establishes Buddhist loving-kindness provenance and displays brief good wishes.",limitation:"Book body and complete scripts were not inspected. The page does not verify every phrase or recipient sequence or establish clinical efficacy. ODA wording and voluntary recipients are adaptations."},{id:"meditation-M19",title:"David Treleaven · Trauma-sensitive mindfulness",url:"https://davidtreleaven.com/",type:"guidance",finding:"The educator warns that sustained inward attention can activate traumatic stress, including flashbacks, distress and dissociation.",limitation:"Homepage and practitioner framing, not an efficacy trial. It does not establish risk frequency or that specific eyes-open, shorter or outward-anchor adjustments prevent harm."},{id:"meditation-M20",title:"Joe Dispenza · Breaking the Habit of Being Yourself · publisher contents",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Publisher contents identify a staged four-week sequence including recognition, declaring, surrendering, redirecting and creating or rehearsing.",limitation:"Book body not inspected. No controlled validation of the branded package or ODA’s combined rehearsal exercise was identified. Planning and task-rehearsal evidence do not establish quantum, genetic, healing or personality claims."},{id:"meditation-M21",title:"Kral et al. · 2022 · Absence of structural brain changes after MBSR",url:"https://doi.org/10.1126/sciadv.abk3316",type:"research",finding:"Across two randomized trials, 218 meditation-naïve participants completed structural scans. Eight-week MBSR produced no detected gray-matter volume, density or cortical-thickness changes against controls.",limitation:"This counters guaranteed structural rewiring. It does not establish no functional changes or no clinical benefit, and does not test ODA."},{id:"meditation-goyal",title:"Goyal et al. · 2014 · Meditation programs for psychological stress and well-being",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"47 randomized trials involving 3,515 adults with clinical conditions or stress found modest average anxiety, depression and pain benefits. Programs included at least four hours of teacher-present training.",limitation:"These were taught programs, not brief ODA practices. No superiority over active treatments was established; that does not prove equivalence. Several outcomes had insufficient evidence."},{id:"meditation-body-scan",title:"Gan, Zhang & Chen · 2022 · Effects of body scan meditation",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 independent randomized-trial articles found a small mindfulness difference versus passive controls: g=.268, 95% CI .032 to .504. Standalone health evidence remains uncertain.",limitation:"Quality was low and heterogeneity high. The abstract does not verify total participants or health-effect estimates. It establishes neither universal ineffectiveness nor brief-scan health benefits."},{id:"meditation-lovingkindness",title:"Zeng et al. · 2015 · Loving-kindness and positive emotions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 empirical reports involved 1,759 people. Eight randomized waitlist comparisons found a modest average daily positive-emotion benefit. Pooled g=.395 or .392 used alternative measurements from one trial.",limitation:"Those estimates are sensitivity variants, not separate energetic and calm effects. Few active comparisons; no guaranteed kindness, relationship improvement or personality change. The bias-percentage denominator is unverified."},{id:"mental-practice",title:"Toth et al. · 2020 · Mental practice and performance",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"The university abstract reports 37 task and skill studies and a small publication-bias-adjusted performance association, r=.131.",limitation:"Full methods, total participants, confidence interval, 115-effects count and older comparison were not verified. This does not establish personality change, healing or the efficacy of ODA’s rehearsal-and-action combination."},{id:"meditation-adverse",title:"Farias et al. · 2020 · Adverse events in meditation practices and therapies",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"83 heterogeneous studies involving 6,703 participants reported adverse experiences. Pooled prevalence was 8.3%, with substantially different estimates in experimental and observational studies.",limitation:"Definitions and ascertainment varied. This is not an individual risk estimate for a brief app session, and reported events were not all established as caused by meditation."},{id:"meditation-nccih",title:"NCCIH · Meditation and mindfulness: effectiveness and safety",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Public guidance cautions against replacing conventional care or delaying assessment. Research on harms is limited; brain images alone do not establish practical health benefits.",limitation:"Guidance is not a trial of ODA. Shortening practice, opening eyes or choosing outward anchors cannot guarantee safety."},{id:"meditation-mind-wandering-cycle",title:"Hasenkamp et al. · 2012 · Mind wandering during focused meditation",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Fourteen experienced meditators marked wandering during breath-focused MRI practice. Researchers modeled wandering, awareness, shifting attention and sustained focus.",limitation:"Small exploratory imaging study, not a beginner intervention. It does not establish brain improvement, health benefits or effects of sound, contact or task-transfer adaptations."},{id:"meditation-trauma-sensitive",title:"David Treleaven · Trauma-sensitive mindfulness",url:"https://davidtreleaven.com/",type:"guidance",finding:"The educator warns that sustained inward attention can activate traumatic stress, including flashbacks, distress and dissociation.",limitation:"Homepage and practitioner framing, not an efficacy trial. It does not establish risk frequency or that specific eyes-open, shorter or outward-anchor adjustments prevent harm."},{id:"meditation-kabat-zinn",title:"Goyal et al. · 2014 · Meditation programs for psychological stress and well-being",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"47 randomized trials involving 3,515 adults with clinical conditions or stress found modest average anxiety, depression and pain benefits. Programs included at least four hours of teacher-present training.",limitation:"These were taught programs, not brief ODA practices. No superiority over active treatments was established; that does not prove equivalence. Several outcomes had insufficient evidence."},{id:"meditation-benson",title:"Harvard Health · 2011 · Benson’s relaxation response",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Practitioner guidance describes comfortable quiet sitting, repeating an acceptable word, sound, phrase or prayer, and returning when thoughts intrude. The recommendation was ten to twenty minutes daily.",limitation:"Blog and anecdote, not an efficacy trial. Complete feet-to-face and exhale instructions, required one-week word use, secular/religious equivalence and a tested short version were not verified."},{id:"meditation-thich-nhat-hanh",title:"Plum Village · Walking meditation",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Traditional guidance attends to foot contact and ordinary breathing. Step coordination is optional and follows a comfortable rhythm; attention can include surroundings.",limitation:"Practice guidance, not an isolated efficacy trial or optimal dose. Keep eyes open and hazards first. Seated and shorter ODA alternatives are adaptations."},{id:"meditation-salzberg",title:"Sharon Salzberg · Lovingkindness book page",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"The author page establishes Buddhist loving-kindness provenance and displays brief good wishes.",limitation:"Book body and complete scripts were not inspected. The page does not verify every phrase or recipient sequence or establish clinical efficacy. ODA wording and voluntary recipients are adaptations."},{id:"dispenza-breaking-habit",title:"Joe Dispenza · Breaking the Habit of Being Yourself · publisher contents",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Publisher contents identify a staged four-week sequence including recognition, declaring, surrendering, redirecting and creating or rehearsing.",limitation:"Book body not inspected. No controlled validation of the branded package or ODA’s combined rehearsal exercise was identified. Planning and task-rehearsal evidence do not establish quantum, genetic, healing or personality claims."}],a=[{schemaVersion:2,revision:2,id:"meditation-1",courseId:"meditation",locale:"en",title:"Your mind wandered. Make one return.",goal:"Practice one comfortable attention return, then do one useful act.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Lost another minute to worry? Give your attention somewhere to return, then use it.",reason:{id:"meditation-1-reason",label:"What deserves your attention, and what is distraction costing?",kind:"text",maxLength:160,optional:!0,suggestions:["Lost drafting time to dinner planning","Missed what someone said","Left a useful task unfinished","No previous occasion"]},why:{id:"meditation-1-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Experienced meditators still notice their minds wandering. In a small breath-focus study, researchers tracked wandering, noticing, returning and staying. The study described attention during practice; it did not prove improved health. You can use that distinction without waiting for a quiet mind.","Choose a comfortable anchor: ordinary breathing, a sound or a visible object. Notice where attention went, then return once. Keep your eyes open if preferred. After this short pause, do one useful act for your chosen task or conversation. Record the return and the act separately; neither requires calm."],example:{title:"Leyla’s first return",text:"At 1:10, Leyla sits at her kitchen table before drafting a volunteer update. She attends to a room sound, notices she is planning dinner, and returns. Then she writes the first useful sentence of the update. Her attention drifts again. She records both the return and the sentence, without claiming a quiet mind."}},move:{invitation:"Keep your act; edit the volunteer-update example.",instructions:["Notice a comfortable anchor, then return when you notice wandering.","Do your chosen useful act; record what happened."],prompts:[],suggestions:{action:["Return; write the volunteer update’s opening sentence","Return; ask when the volunteer shift starts"],minimum:["Make one return; write one update sentence","Return; ask one question about the shift"],cue:["After lunch, before drafting the volunteer update","When the volunteer coordinator invites questions"],place:["Kitchen table, seated with eyes open","In the volunteer coordinator’s message thread"],minutes:[2,1,3],fallback:["Use a visible object; write the update sentence","Pause and choose support"],observation:["Attention return and update sentence written","What anchor felt workable"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Return; write the volunteer update’s opening sentence",minimum:"Make one return; write one update sentence",minutes:2,cueHint:"After lunch, before drafting the volunteer update",placeHint:"Kitchen table, seated with eyes open",obstacleHint:"Watching my breath feels uncomfortable",fallbackHint:"Use a visible object; write the update sentence",observationHint:"Attention return and update sentence written"},stopRule:"Stop for growing distress, dizziness or detachment. Orient outward; seek support if symptoms persist or concern you.",accessibleAlternative:"Keep eyes open; use sound, a visible object or seated contact."},result:{question:"Did you return and do your chosen useful act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-1-decision",scenario:"Leyla’s one-minute sound practice is restless but tolerable. She notices dinner planning. Her update still needs its first sentence.",question:"What fits this attempt?",options:[{id:"meditation-1-restart",text:"Restart the minute for a cleaner practice before beginning the update.",feedback:"A fresh start is tempting, but the planned pause was not a concentration test. Return once, finish as planned, and write the useful sentence."},{id:"meditation-1-return",text:"Return to the sound, finish the pause, then write the sentence.",feedback:"This tests the chosen skill and its purpose. A restless pause can contain a real return; the sentence shows what happened afterward, without proving calm."},{id:"meditation-1-solve",text:"Use the remaining pause to settle dinner plans before starting the update.",feedback:"Solving dinner may feel productive, but it changes this attempt’s purpose. Note the thought if needed, return to the anchor, then do the chosen act."}],bestOptionId:"meditation-1-return"}},carry:{takeaway:"Practice the return, then use your attention for something you chose.",followUp:{questionId:"meditation-1-return",question:"Did the return lead to your chosen act, or stop at the pause?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Experienced minds wander too",paragraphs:["Hasenkamp and colleagues studied fourteen experienced meditators during twenty minutes of breath-focused practice in an MRI scanner. Participants attended to sensations at the nostrils or upper lip. They pressed a button when they realized attention had completely wandered, then returned. Researchers modeled four phases: wandering, awareness, shifting back and sustained focus. This is a useful description of one task, not a prescription for how long everyone should sit. (meditation-M08)","The imaging associations do not establish that each return rewires your brain, increases intelligence or changes health. ODA’s sound anchor, open eyes and short introductory pause differ from the laboratory procedure. Use them as voluntary adaptations. In your record, distinguish attending, noticing a drift and returning. You do not need to count every thought or manufacture wandering to meet a target."]},{heading:"A short pause has a different promise",paragraphs:["Goyal’s review included forty-seven randomized trials and 3,515 adults with clinical conditions or stress. Programs involved at least four hours of teacher-present training. Average anxiety, depression and pain outcomes favored some mindfulness programs modestly. These findings do not establish those outcomes from a one-minute ODA pause. The review found no superiority over active treatments; that does not demonstrate equivalence to them. (meditation-M01)","Your experiment has a narrower question: can you choose an anchor, return and then use attention for an ordinary act? ODA has not tested this combination. A useful sentence, a question or a decision to pause can be reported without a health claim. NCCIH cautions against replacing care or delaying assessment. Keep prescribed care and seek appropriate support when practice or symptoms concern you. (meditation-M03)"]}],sourceIds:["meditation-M08","meditation-M01","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-2",courseId:"meditation",locale:"en",title:"Notice discomfort before you push through",goal:"Test comfortable contact, make a practical adjustment, then return to your chosen act.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Ignored your uncomfortable chair again? Notice enough to make a useful choice.",reason:{id:"meditation-2-reason",label:"What need are you overriding to keep going?",kind:"text",maxLength:160,optional:!0,suggestions:["Uncomfortable seating","A break I needed","Pain that needs assessment","No need I noticed"]},why:{id:"meditation-2-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A body scan notices sensations; it does not diagnose them. In one eight-week study, body scanning did not outperform an audiobook on a heartbeat-counting task. Another comparison favored scanning over doing nothing. That difference matters: noticing your body is not a proven shortcut to better health.","Use this only if your earlier anchor felt awkward or you overlooked an ordinary need. Briefly notice two comfortable contact points, such as hands and seat. No clear sensation is an observation. Make one practical adjustment if useful, then do the same act you chose earlier. You may stay with an outward anchor instead."],example:{title:"Leyla changes the chair",text:"Before the next update session, Leyla notices her hands on the table and her seat on a hard chair. She chooses a cushion, then writes one useful sentence. Her shoulders still feel tense. She records the adjustment and sentence. She keeps room sounds as an alternative rather than committing to a full body scan."}},move:{invitation:"Keep your act; edit the chair-and-update example.",instructions:["Notice two comfortable contact points, or choose an outward anchor.","Make an ordinary adjustment, then do the same useful act."],prompts:[],suggestions:{action:["Adjust chair; write volunteer update’s opening sentence","Notice contact; ask when the volunteer shift starts"],minimum:["Write opening sentence after a comfortable contact check","Notice contact; ask one shift question"],cue:["After sitting for the volunteer update","When the volunteer coordinator invites questions"],place:["Kitchen table, using a comfortable chair","In the volunteer coordinator’s message thread"],minutes:[3,2,1],fallback:["Use room sounds; write the update sentence","Pause and request suitable support"],observation:["Comfort adjustment and update sentence written","Whether contact felt comfortable"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Adjust chair; write volunteer update’s opening sentence",minimum:"Write opening sentence after a comfortable contact check",minutes:3,cueHint:"After sitting for the volunteer update",placeHint:"Kitchen table, using a comfortable chair",obstacleHint:"Contact focus becomes uncomfortable",fallbackHint:"Use room sounds; write the update sentence",observationHint:"Comfort adjustment and update sentence written"},stopRule:"Stop if distress grows. New or persistent pain, numbness or concerning symptoms need medical assessment.",accessibleAlternative:"Use open eyes and room sounds; seated, nonmovement practice is enough."},result:{question:"Did you make a practical choice and do your act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-2-decision",scenario:"At her table, Leyla notices familiar shoulder tension. Focusing on it grows uncomfortable. Her update still needs one sentence.",question:"What fits this attempt?",options:[{id:"meditation-2-extend",text:"Scan additional regions first to understand the tension before choosing an adjustment.",feedback:"More observations can feel informative, but discomfort is growing and this exercise cannot explain its cause. Stop or shift outward, then choose a practical response."},{id:"meditation-2-hold",text:"Keep attention on the shoulder until it relaxes, then write the sentence.",feedback:"Waiting for relaxation makes a feeling the entry requirement. You can stop the uncomfortable focus, adjust the setting and write if appropriate without changing that feeling."},{id:"meditation-2-adapt",text:"Shift to room sounds, adjust the chair, then write if the setting fits.",feedback:"This preserves choice and the useful act while responding to discomfort. A contact exercise is optional; it does not require enduring unpleasant focus or diagnosing a sensation."}],bestOptionId:"meditation-2-adapt"}},carry:{takeaway:"Noticing earns its place when it informs a responsible next choice.",followUp:{questionId:"meditation-2-return",question:"Did you make a useful adjustment and then do your chosen act?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"A sensation is not a diagnosis",paragraphs:["Fischer and colleagues examined eight weeks of daily twenty-minute guided body scanning in small student samples. The recording moved attention through body regions and included whole-body attention and a closing phase. The complete script and region timings were not printed. ODA’s brief contact exercise is an adaptation rather than a reconstruction of that tested recording. (meditation-M07)","In Study 1, heartbeat-counting change was not significantly greater than with an audiobook. Study 2 favored scanning over an inactive comparison. Neither result establishes disease detection, interpretation of every bodily need or a health effect from today’s abbreviated exercise. “No clear sensation noticed” describes attention during this attempt. It must not be used to relabel new numbness, dismiss pain or postpone medical assessment. An ordinary comfort adjustment and a medical help request serve different needs."]},{heading:"Choose fit without claiming treatment",paragraphs:["Gan and colleagues reviewed fourteen independent randomized-trial articles about standalone body scanning. They reported a small mindfulness difference against passive controls, with low study quality and substantial variation. Standalone health benefits remain uncertain. That is neither proof that scanning never helps anyone nor evidence that a short scan is better than a long one. (meditation-M06)","Your comparison is about fit: was contact comfortable enough to use, and did you make a useful choice afterward? Keep the same chosen act so changing the anchor does not create a separate course project. Open eyes, outward attention, skipped regions and shortening are precautionary options, not verified trauma treatment or guaranteed protection. NCCIH advises keeping medical care and avoiding delayed assessment. An honest paused record can support a decision to get help, rest or use another suitable setting. (meditation-M03)"]}],sourceIds:["meditation-M07","meditation-M06","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-3",courseId:"meditation",locale:"en",title:"Breath watching awkward? Try one word.",goal:"If your anchor was awkward, test a neutral word before the same useful act.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Checking your breathing instead of doing your task? Try one neutral word.",reason:{id:"meditation-3-reason",label:"Will this pause support your act or postpone it?",kind:"text",maxLength:160,optional:!0,suggestions:["Supports the act when my anchor feels awkward","Postpones the act while I check for calm","Unsure until I try"]},why:{id:"meditation-3-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A repeated word is another anchor, not a stronger command. Benson’s practitioner guidance describes returning to a chosen word when thoughts intrude. It does not establish that a neutral word and a prayer have identical effects, or that one word must be kept for a week.","If breathing or contact felt awkward in your record, try an acceptable word such as “here.” Keep ordinary breathing and an easy gaze. When you notice distraction, return to the word. End at your chosen point, then do the same useful act. If your existing anchor fits, repeat it instead. Feeling calm is not the pass mark."],example:{title:"Leyla tries “here”",text:"Leyla’s record says breath watching made her check each inhale. At 1:10 the next day, she uses “here” as a quiet anchor for one minute, eyes open. She returns after a shopping thought, then writes her update sentence. The word feels ordinary rather than soothing. She records that and keeps the sentence as her useful minimum."}},move:{invitation:"Keep your act; edit the word-and-update example.",instructions:["Return to one acceptable word without adjusting your breathing.","End the pause, then do your same useful act."],prompts:[],suggestions:{action:["Use “here”; write volunteer update’s opening sentence","Use room sounds; ask when volunteer shift starts"],minimum:["Return to “here”; write the update sentence","Return once; ask one shift question"],cue:["After lunch, before writing the volunteer update","When the volunteer coordinator invites questions"],place:["Kitchen table, seated with eyes open","In the volunteer coordinator’s message thread"],minutes:[2,1,3],fallback:["Finish pause, then write the update sentence","End the pause and seek support"],observation:["Word tolerability and update sentence written","The useful act after the pause"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use “here”; write volunteer update’s opening sentence",minimum:"Return to “here”; write the update sentence",minutes:2,cueHint:"After lunch, before writing the volunteer update",placeHint:"Kitchen table, seated with eyes open",obstacleHint:"I start testing whether I feel calm",fallbackHint:"Finish pause, then write the update sentence",observationHint:"Word tolerability and update sentence written"},stopRule:"Stop for growing distress, dizziness or detachment; orient outward and get support if needed.",accessibleAlternative:"If the word is uncomfortable, choose sound or a visible object. Keep eyes open."},result:{question:"Did you end the pause and do your chosen act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-3-decision",scenario:"Leyla’s word feels neutral and tolerable, but she keeps checking for calm. Her planned minute is almost over.",question:"What fits this attempt?",options:[{id:"meditation-3-end",text:"Return to the word, finish the planned minute, then write her sentence.",feedback:"The word supplies an anchor, not a mood test. Ending as planned keeps the useful act available. Record tolerability and the actual sentence rather than demanding calm."},{id:"meditation-3-switch",text:"Try another word for the remaining minute to find a more soothing one.",feedback:"Changing an uncomfortable anchor can be reasonable. Here the word is tolerable; repeated searching answers a different question and risks replacing the useful act with mood checking."},{id:"meditation-3-lengthen",text:"Add a second minute so the word has more time to produce calm.",feedback:"Extra practice is a choice, but no evidence establishes a required calming dose here. Finish the feasible pause and do the act before deciding whether another trial helps."}],bestOptionId:"meditation-3-end"}},carry:{takeaway:"Choose an anchor you can use; judge the act that follows separately.",followUp:{questionId:"meditation-3-return",question:"Was the word workable, and did your chosen act follow?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Where the word practice comes from",paragraphs:["The Harvard Health account of Benson’s relaxation response describes comfortable sitting, quiet surroundings, a chosen word, sound, phrase or prayer, and returning when thoughts intrude. Its practitioner recommendation is ten to twenty minutes daily. It is a blog and personal account rather than a trial of every listed step. The opened page does not verify a complete feet-to-face relaxation script or a required exhale sequence. (meditation-M16)","ODA’s shorter word trial, open eyes and neutral wording are adaptations. They do not inherit an established medical effect from that page. You can choose a prayer privately if it fits your beliefs, but no comparative trial here establishes equal effects for religious and secular anchors. Nor does the page establish a necessary one-week word commitment. Choose based on acceptability and your actual record rather than historical fidelity."]},{heading:"A review of mantras is broader than this trial",paragraphs:["Álvarez-Pérez and colleagues combined fifty-one studies of varied mantra-based practices. Their anxiety analysis included twenty-five studies and 1,825 people. The average estimate favored intervention, but the prediction interval included no benefit. No study was rated overall low risk of bias, and follow-up was limited. These qualifications matter when a named method is offered as a universal solution. (meditation-M12)","The review does not validate Benson’s exact method, today’s one-minute word anchor or superiority over other practices. No purchase or paid training is necessary for this voluntary experiment. Keep the same real-life act while testing one anchor change so the record stays interpretable. Describe what you used and what followed; a single favorable day cannot prove the word caused improvement. NCCIH’s care boundary still applies, including when a practice feels pleasant. (meditation-M03)"]}],sourceIds:["meditation-M16","meditation-M12","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-4",courseId:"meditation",locale:"en",title:"Arrive before your phone does",goal:"Use one safe transition to return attention, then do your chosen act on arrival.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Reached your desk still inside your phone? Use one transition to arrive on purpose.",reason:{id:"meditation-4-reason",label:"Which arrival habit will you give up so your chosen act can start?",kind:"text",maxLength:160,optional:!0,suggestions:["Delay messages until after the first sentence","Put phone away before the conversation","No competing habit noticed"]},why:{id:"meditation-4-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Walking attention uses foot contact and ordinary breathing. Plum Village’s guidance offers step coordination as an option, not a required breathing ratio. It is traditional instruction rather than proof of a special health effect. Your surroundings take priority over an anchor.","If your earlier pause keeps getting crowded out, use an existing transition. Keep eyes open and move at a safe pace. Notice contact only where it does not compete with hazards. A seated, stationary version works as an adaptation. At the destination, do your same useful act. This tests arrival and follow-through, not how slowly you can walk."],example:{title:"Leyla’s library arrival",text:"Leyla keeps missing the kitchen cue, so she tries her usual library arrival. She watches crossings normally and notices a few foot contacts in the quiet entrance. At her table she puts her phone aside and writes one useful update sentence. A later notification still interrupts her. She records the arrival and sentence rather than calling the day distraction-free."}},move:{invitation:"Keep your act; edit the library-arrival example.",instructions:["Keep eyes open and surroundings first; breathing stays ordinary.","At your destination, do the same useful act."],prompts:[],suggestions:{action:["Arrive; write the volunteer update’s opening sentence","Arrive; ask when the volunteer shift starts"],minimum:["Notice seated contact; write one update sentence","Notice contact; ask one shift question"],cue:["When I arrive at the library table","When I arrive for the volunteer check-in"],place:["At the library writing table","At the accessible volunteer meeting table"],minutes:[2,1,3],fallback:["Notice seated contact at arrival","Skip the anchor and attend to hazards"],observation:["Library arrival and update sentence written","Whether the transition cue occurred"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Arrive; write the volunteer update’s opening sentence",minimum:"Notice seated contact; write one update sentence",minutes:2,cueHint:"When I arrive at the library table",placeHint:"At the library writing table",obstacleHint:"The route demands all my attention",fallbackHint:"Notice seated contact at arrival",observationHint:"Library arrival and update sentence written"},stopRule:"Keep eyes open. Stop anchor practice when hazards compete; stop and seek support if distress or dizziness grows.",accessibleAlternative:"Use a seated, stationary sound or contact anchor; no movement is required."},result:{question:"Did you arrive safely and do your chosen act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-4-decision",scenario:"Leyla’s route has crowded crossings. Her chosen writing table is available when she arrives. She planned attention to foot contact.",question:"What fits this attempt?",options:[{id:"meditation-4-count",text:"Preserve her step rhythm on the route, then write at the table.",feedback:"A familiar rhythm may appeal, but crossings need attention. Drop counting whenever it competes with hazards; the useful act can still happen at the destination."},{id:"meditation-4-arrive",text:"Attend to the crossings, notice seated contact on arrival, then write.",feedback:"This keeps safety first and tests the chosen arrival cue. Seated contact is an ODA adaptation, not a lesser result or a proven equivalent treatment."},{id:"meditation-4-relocate",text:"Wait for a quiet park route before returning to the writing experiment.",feedback:"A park may fit another practice, but her task space is available now. Use a safe stationary arrival anchor rather than making an ideal route a prerequisite."}],bestOptionId:"meditation-4-arrive"}},carry:{takeaway:"Let safe arrival support your chosen act; the route is not a concentration test.",followUp:{questionId:"meditation-4-return",question:"Did the transition help you start your chosen act?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Rhythm follows the route",paragraphs:["Plum Village’s walking guidance attends to feet contacting the ground, ordinary breathing and the surrounding world. It gives examples of coordinating steps with a comfortable breath rhythm. Those examples are not respiratory targets to force, and the page is practitioner guidance rather than an isolated walking-meditation efficacy trial. The tradition’s spiritual language is not evidence of medical healing. (meditation-M17)","ODA uses a short, familiar transition only when it addresses a problem in your earlier record, such as a seated cue that rarely occurs. Keep eyes open everywhere, including quiet paths. Drop counts when they interfere with route awareness. A seated or stationary anchor is an accessibility adaptation, not a scientifically established equivalent. Your useful act belongs at the destination; record it separately from the walk or arrival pause."]},{heading:"An existing transition can become a cue",paragraphs:["Gollwitzer and Sheeran’s review combined ninety-four independent tests of situation-linked response plans. On average, these plans supported goal attainment across varied domains. Most participants were university students, and the synthesis does not establish an effect for this library-arrival routine. It supports a bounded planning idea: choose a recognizable opportunity and a feasible response. (meditation-M05)","“When I reach my table, I return once and write my first useful sentence” names both the opportunity and behavior. If the destination is unavailable, choose an accessible alternative rather than pretending the original attempt happened. A busy route is a real constraint, not poor discipline. This adaptation does not borrow benefits from exercise research or promise less rumination. NCCIH cautions against replacing care and notes limited harm research; being outside does not make every practice suitable. (meditation-M03)"]}],sourceIds:["meditation-M17","meditation-M05","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-5",courseId:"meditation",locale:"en",title:"Keep the boundary. Drop the sting.",goal:"If harshness blocks your act, try an optional good wish before a clear response.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"About to add a jab to your reply? Keep your point without the extra sting.",reason:{id:"meditation-5-reason",label:"What boundary or useful point should survive this reply?",kind:"text",maxLength:160,optional:!0,suggestions:["I cannot cover Sunday","My actual available hours","The information needed for the update"]},why:{id:"meditation-5-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Loving-kindness studies measure reported feelings, not guaranteed kindness in behavior. A review found modest average positive-emotion benefits, mostly against waitlists. That does not prove a brief wish will improve your reply or repair a relationship.","Use this option if your record shows harshness getting in the way of your chosen act. Offer one voluntary wish to yourself or a safe loved person: “May you have support.” Warmth is optional. Then do your same useful act, such as sending a clear sentence without a jab. Keep the boundary. Skip wishes or stop if they hurt; contact with an unsafe person is never required."],example:{title:"Leyla’s firm sentence",text:"Leyla’s update needs a reply about extra volunteer work. Her draft includes “As you should already know.” At her table, she offers a quiet wish for her sister, then removes the jab and sends her sentence: “I can cover Saturday, but not Sunday.” She still feels annoyed. She records the sent boundary, without crediting the wish for a better relationship."}},move:{invitation:"Keep your act; edit the volunteer-reply example.",instructions:["Choose yourself or a safe recipient; warmth is optional.","Use your clear sentence while preserving the point or boundary."],prompts:[],suggestions:{action:["Tell coordinator I can cover Saturday only","Write the update sentence without self-attack"],minimum:["Send Saturday availability without the jab","Write one usable volunteer update sentence"],cue:["Before replying to the volunteer coordinator","After lunch, before writing the volunteer update"],place:["In the volunteer coordinator’s message thread","At the kitchen writing table"],minutes:[2,1,3],fallback:["Skip wishes; send the clear availability sentence","Pause and choose protection or support"],observation:["Availability sentence sent; reply or silence","Whether wishes felt acceptable"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Tell coordinator I can cover Saturday only",minimum:"Send Saturday availability without the jab",minutes:2,cueHint:"Before replying to the volunteer coordinator",placeHint:"In the volunteer coordinator’s message thread",obstacleHint:"The wish feels painful or forced",fallbackHint:"Skip wishes; send the clear availability sentence",observationHint:"Availability sentence sent; reply or silence"},stopRule:"Stop distressing wishes; use outward attention or support. Keep boundaries and avoid unsafe contact.",accessibleAlternative:"Keep eyes open; choose a safe recipient, neutral wording or no wishes."},result:{question:"Did you use your clear sentence or chosen act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-5-decision",scenario:"Leyla’s safe volunteer coordinator requests Sunday work. She cannot cover it. Her draft has a jab, and she still feels annoyed.",question:"What fits this attempt?",options:[{id:"meditation-5-delay",text:"Hold the reply until the good wish changes her annoyed feeling.",feedback:"A delay can help when facts are missing. Here her availability is clear. She can remove the jab and send the boundary without waiting for warmth."},{id:"meditation-5-accept",text:"Send the original reply because the jab might make the Sunday limit unmistakable.",feedback:"Wanting the limit taken seriously makes the jab tempting. A clear availability sentence already communicates it; the extra criticism risks distracting from the boundary she needs to preserve."},{id:"meditation-5-send",text:"Remove the jab, state her availability, and send the clear reply now.",feedback:"This carries the chosen act into life without making emotion the gate. An optional wish may accompany it; the evidence is the sentence she actually sends."}],bestOptionId:"meditation-5-send"}},carry:{takeaway:"A voluntary wish can accompany a clear act; it never requires surrendering your boundary.",followUp:{questionId:"meditation-5-return",question:"Did your actual sentence keep the point and remove any unnecessary sting?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Positive feeling is a different outcome",paragraphs:["Zeng and colleagues reviewed twenty-four reports involving 1,759 people. Eight randomized waitlist comparisons informed the daily positive-emotion estimate. The pooled values .395 and .392 came from choosing alternative arousal measurements in one trial. They are alternative estimates of the same outcome, not separate effects on energetic and calm emotions. Few studies used active comparisons. (meditation-M09)","Another early workshop included six instructor-led sessions over seven weeks plus home recordings. Its condition-by-week positive-emotion effect was significant among 139 completers, but not in intent-to-treat or per-protocol analyses. Exclusions and waitlist comparison limit what can be concluded. A short wish before writing is not that workshop. Neither paper establishes that wishes make you kinder, improve this relationship or cause the invented example’s clear reply. (meditation-M11)"]},{heading:"Intention, choice and boundaries",paragraphs:["Salzberg’s author page establishes the loving-kindness tradition and displays brief good wishes. The author page does not supply a complete script or establish every phrase and recipient order. Today’s original wording, safe recipient choice and abbreviated practice are ODA adaptations, not a complete teacher protocol. A difficult person is optional and never a requirement for completion. (meditation-M18)","Keep the distinction between an intention and a feeling. You may offer a wish without warmth, choose someone safe rather than yourself, skip the practice or stop if it becomes distressing. None of those choices decides whether your boundary is valid. Review the actual sentence: what was necessary, what was a jab, and what response followed? An unchanged mood or unanswered message is still a factual record. Use your previous anchor if it fits better; the course experiment remains your chosen useful act."]}],sourceIds:["meditation-M09","meditation-M11","meditation-M18"]}},{schemaVersion:2,revision:2,id:"meditation-6",courseId:"meditation",locale:"en",title:"Rehearse the response you keep missing",goal:"If a familiar trigger derails your act, prepare one response and use it at the cue.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still sent the sharp message? Rehearse your actual response.",reason:{id:"meditation-6-reason",label:"What did the last reaction cost, and what response is yours to change?",kind:"text",maxLength:160,optional:!0,suggestions:["Sent words I later had to repair","Missed a useful opening","Left the unresolved detail unclear","No earlier attempt"]},why:{id:"meditation-6-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Mental-practice research concerns tasks and skills, not creating a new personality. Across thirty-seven studies, the bias-adjusted average performance association was small. It did not validate emotional surrender, thought-driven healing or a required three-repeat ritual.","Use rehearsal if your record shows a specific trigger blocking the same useful act. Name the cue and one response you control. Optionally picture it once, or write the line without imagery. Then use that response at a safe real opening. Preparation alone stays preparation. If the cue never occurs, record no occasion; you do not owe an invented success or a calmer feeling."],example:{title:"Leyla’s late-update question",text:"At 9:00, Leyla writes “What is still missing?” because late updates often pull her into a sharp reply. She briefly pictures asking it, then saves the noon conversation as her real action. The report is late. She asks the question and learns a detail is unresolved. She records the question, not a transformed personality or a smooth meeting."}},move:{invitation:"Keep your act; edit the late-update example.",instructions:["Name your real opening before saving; optional rehearsal remains preparation.","Use your saved response there; a writing act need not become a conversation."],prompts:[],suggestions:{action:["Ask the coordinator what is still missing","Write the volunteer update’s next factual sentence"],minimum:["Ask what is still missing","Write one factual volunteer update sentence"],cue:["When the volunteer update arrives late","When I open the unfinished volunteer update"],place:["In the volunteer coordinator’s message thread","At the kitchen writing table"],minutes:[2,1,3],fallback:["Use written “What is still missing?”","Choose the next suitable real opening"],observation:["Late update, actual question, and reply or silence","What happened after my response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask the coordinator what is still missing",minimum:"Ask what is still missing",minutes:2,cueHint:"When the volunteer update arrives late",placeHint:"In the volunteer coordinator’s message thread",obstacleHint:"The trigger occurs before I remember the line",fallbackHint:"Use written “What is still missing?”",observationHint:"Late update, actual question, and reply or silence"},stopRule:"Pause if the setting is unsafe or distress grows. Choose protection, support or an outward anchor.",accessibleAlternative:"Name the actual response and opening before saving. Writing, signing and no imagery are valid."},result:{question:"Did you use the response at the real opening?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-6-decision",scenario:"Leyla knows her question and has a safe opening with the coordinator. The late update arrives; she feels annoyed.",question:"What fits this attempt?",options:[{id:"meditation-6-ideal",text:"Picture the whole discussion going smoothly before deciding whether to ask her question.",feedback:"A smooth scene can feel reassuring, but it avoids the cue already present. She has a usable question and safe opening; use it and record the response."},{id:"meditation-6-ask",text:"Notice the late update, then ask her prepared question before commenting further.",feedback:"This tests the actual response linked to the cue. Annoyance can remain. Rehearsal was preparation; asking and recording the reply supplies the real-life evidence."},{id:"meditation-6-rehearse",text:"Rehearse the question several more times so her delivery feels fully steady.",feedback:"More rehearsal may serve a genuine skill gap. In this case the question is ready; additional preparation could lose the opening. Ask once without requiring steady feelings."}],bestOptionId:"meditation-6-ask"}},carry:{takeaway:"Rehearse a behavior you can use, then record whether you used it.",followUp:{questionId:"meditation-6-return",question:"Did the cue appear, and did you use the response rather than only rehearse it?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Task rehearsal has a narrower evidence base",paragraphs:["Toth and colleagues’ institutional abstract reports thirty-seven studies of mental practice published from 1995 to 2018. The bias-adjusted performance association was small, r=.131. The abstract does not supply full methods, participant total, or a confidence interval. It also does not verify the older comparison or total number of effects. (meditation-M13)","This evidence concerns tasks and skills. It does not establish personality change, emotion release or healing, and does not test today’s particular cue, question or optional single rehearsal. Writing or imagining a response can be recorded as preparation. The later real response has its own occurrence and outcome. Keep them separate so a successful rehearsal never stands in for a conversation that did not happen. No particular emotional state or repetition count is required."]},{heading:"A response plan without an identity ritual",paragraphs:["Gollwitzer and Sheeran’s goal-planning review supports linking a recognizable situation to a feasible response across varied domains. It does not validate every combined rehearsal routine. “If the update is late, then I ask what is missing” specifies an act under your control; “be a calm leader” does not name one. The timing and wording here are ODA choices. (meditation-M05)","Dispenza’s publisher contents identify stages in a four-week package, but the book body was not inspected and controlled validation of that combined package was not identified. Planning and task-rehearsal findings cannot establish its surrender, quantum, genetic or healing claims. Treat a safe opening as a chance to test the line, rather than wait to feel changed. Use an observable response, allow feelings to remain, and review any consequence or repair that belongs to your actual behavior. Keep prescribed care. (meditation-M20)"]}],sourceIds:["meditation-M13","meditation-M05","meditation-M20"]}},{schemaVersion:2,revision:2,id:"meditation-7",courseId:"meditation",locale:"en",title:"Keep what survived a real day",goal:"Review your attention-and-action records, keep a workable version, and schedule the next attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Liked the lessons but lost the routine? Build next week from what you actually tried.",reason:{id:"meditation-7-reason",label:"What will you protect, shrink or stop next week?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the library arrival cue","Shrink pause; keep the act","Stop distressing practice","No record; choose a first act"]},why:{id:"meditation-7-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Repetition in a stable context can become more automatic, but habit timing varies. One observational study followed everyday behaviors, not meditation. Its modeled times do not establish a twenty-one-day or sixty-six-day deadline for your practice.","Review your same experiment: which cues occurred, which anchors were tolerable, and which useful acts actually followed? Keep a version supported by a record, or schedule a first trial if you have none. Plan three suitable opportunities next week as a course choice, not a required dose. Start with the next one; each gets its own record. Support, rest or stopping may be the appropriate decision."],example:{title:"Leyla keeps the workable cue",text:"On Sunday, Leyla checks three records. Kitchen practice happened once; library arrivals happened twice, each followed by an update sentence. She keeps the library cue and schedules Monday’s short version. On Monday she returns to a room sound and writes one sentence. It feels busy rather than peaceful. She records it and leaves later days unclaimed."}},move:{invitation:"Keep your act; edit the towel-folding example.",instructions:["Keep your saved action, minimum, cue and place; otherwise choose an example or first act.","Set the new start cue before saving a changed plan.","Log support, rest, or another act using its own minimum."],prompts:[],suggestions:{action:["Return to room sounds; fold one towel","Return; listen through one volunteer update"],minimum:["Fold one towel after one attention return","Listen until the speaker finishes one update"],cue:["After lunch dishes are put away","When the volunteer check-in begins"],place:["At the kitchen table","At the accessible volunteer meeting table"],minutes:[2,1,3],fallback:["Choose available cue; keep the tolerable anchor","Pause without scheduling another attempt"],observation:["Cue, attention return, and towel folded","Update heard; interruption or no interruption"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Return to room sounds; fold one towel",minimum:"Fold one towel after one attention return",minutes:2,cueHint:"After lunch dishes are put away",placeHint:"At the kitchen table",obstacleHint:"The after-lunch cue no longer fits my week",fallbackHint:"Choose available cue; keep the tolerable anchor",observationHint:"Cue, attention return, and towel folded"},stopRule:"Stop for distress, dizziness or detachment; seek qualified help for recurring concerns. Do not delay care.",accessibleAlternative:"Use outward, seated or nonmovement practice. Set a changed start cue before saving. For help, choose Adapt and Support; name the request and its minimum."},result:{question:"Did you try the next version or chosen support act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-7-decision",scenario:"Leyla’s records show crowded mornings and two workable library arrivals. She wants attention for the same update task next week.",question:"What fits this attempt?",options:[{id:"meditation-7-restore",text:"Protect longer morning sessions next week because the original routine deserves a fair trial.",feedback:"A longer trial might fit changed circumstances, but her records identify crowded mornings now. Use the observed library cue before increasing a plan that rarely happens."},{id:"meditation-7-rotate",text:"Choose a different technique each day to find one that renews her interest.",feedback:"Exploration can be useful, but her records already show a tolerable anchor and available cue. Changing everything would make the known bottleneck harder to evaluate."},{id:"meditation-7-keep",text:"Keep the library cue and tolerable anchor, then schedule her next useful sentence.",feedback:"This uses actual attempts to choose a feasible next version. Later opportunities remain plans until tried. Review each record without requiring calm or a perfect week."}],bestOptionId:"meditation-7-keep"}},carry:{takeaway:"Keep a workable return and useful act. Let your records guide the next week.",followUp:{questionId:"meditation-7-return",question:"What happened with your chosen act or support request, and what needs to change?",observationPrompt:"What was done, and what response or next step is still pending?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"A week is a review window",paragraphs:["Lally and colleagues followed ninety-six volunteers for eighty-four days as they repeated eating, drinking or activity behaviors in recurring contexts. Eighty-two supplied sufficient data; thirty-nine had acceptable automaticity models. Their estimated times varied widely and partly extended beyond the observation period. The median sixty-six-day estimate is a modeling result, not a habit-completion deadline or a meditation finding. (meditation-M14)","The observed omission analysis found no significant subsequent automaticity reduction after one missed opportunity, but omissions were not randomized. It cannot guarantee what every future miss means. ODA’s three suitable opportunities and weekly review are design choices. Use them to see whether the cue, size and setting fit your real life. A later date is not a completed attempt. Keep previous records intact when changing the next plan; a new minimum does not rewrite an earlier promise."]},{heading:"Stopping belongs in the continuing plan",paragraphs:["NCCIH advises against replacing medical care or delaying assessment and notes limited harm research. Farias and colleagues’ review combined eighty-three heterogeneous studies, including observational reports and experiments. Its pooled 8.3% adverse-event estimate is not a probability for your next brief app session; definitions, doses and ascertainment differed substantially. Difficult experiences are not proof that practice is working. (meditation-M03; meditation-M04)","Keep a stop route with whichever anchor you retain. Eyes-open, short, outward or seated choices are precautions, not guarantees. Recurring distress or concerns about detachment warrant qualified mental health support; a meditation teacher does not replace assessment. A plan for rest or a help request can serve your life better than another sit. The continuing experiment tests fit and a useful act, not symptom cure, constant calm, perfect attendance or an obligation to practice every technique."]}],sourceIds:["meditation-M14","meditation-M03","meditation-M04"]}}],n=[{id:"meditation-1",practice:["Sit safely for a chosen short time, such as one minute; a timer is optional.","Use ordinary breath sensations, an eyes-open sound or a visible object as your anchor.","When you notice wandering, return once; stop if distress, dizziness or detachment grows."],reflection:"Where did your attention wander most, and how did it feel to come back?",question:"If your attention keeps wandering during a sit, what does that mean?",options:["Meditation is not for me, and I should stop.","Noticing the wandering and coming back is the exercise itself.","I should push myself harder until my mind is completely empty."],correct:1,feedback:"Wandering is normal. In mindfulness meditation the goal is not a thought-free mind but the skill of noticing and gently coming back.",photo:{id:"1758273240112-c7724c9bb4a5",alt:"A young woman meditating with her eyes closed on the floor at home"}},{id:"meditation-2",practice:["Choose a comfortable seated or lying position and a feasible short duration; keep eyes open if preferred.","Optionally notice comfortable contact points, skip uncomfortable regions or use an outward anchor.","Name what you actually noticed, make a practical adjustment if useful, and stop if distress grows."],reflection:"Which part of your body felt new or surprising to notice?",question:"During a body scan, what do you do if you feel nothing in one area?",options:["I tense or move that area until I feel something.","I notice “no clear sensation here” and move on.","I assume I did it wrong and start again from the beginning."],correct:1,feedback:"Not noticing a clear sensation is an attentional observation, not a diagnosis of numbness. Do not force sensations; new or persistent concerning symptoms warrant medical assessment.",photo:{id:"1535987271305-c26a8935f74a",alt:"A woman lying on the grass in sunlight, resting"}},{id:"meditation-3",practice:["Choose an acceptable short word, sound, phrase or private prayer, if you want a verbal anchor.","Sit comfortably for a chosen short time; keep eyes open if preferred and breathing ordinary.","Return to your word when thoughts intrude, or stop or shift outward if discomfort grows."],reflection:"How did the word you chose feel, and will you use the same one tomorrow?",question:"In Benson’s method, what do you do when thoughts come in?",options:["I push the thought away and empty my head.","I stop the sit halfway; it means I cannot focus.","Without forcing, I notice the thought and return to my word."],correct:2,feedback:"The practitioner guidance describes returning without forcing. It does not require a particular phrase, breathing pattern or week of using one word; stop or adapt if distress grows.",photo:{id:"1513097847644-f00cfe868607",alt:"A woman sitting quietly on a wooden jetty in sunlight"}},{id:"meditation-4",practice:["Choose a safe familiar route, or use a seated, stationary contact alternative.","Keep eyes open, attend to hazards and breathe normally; comfortable step coordination is optional.","For a chosen short period, notice safe contact or surroundings; stop counting whenever safety requires attention."],reflection:"While walking slowly, what did you see or hear that you had not noticed before?",question:"In walking meditation, how is the number of steps decided?",options:["It is fixed for everyone: four steps per breath.","It is adjusted to your own breathing rhythm and pace.","The goal is to take as many steps as possible."],correct:1,feedback:"Optional step coordination follows a comfortable natural rhythm. Keep eyes open and surroundings first; no fixed ratio or isolated health effect is established by this practice guidance.",photo:{id:"1477332552946-cfb384aeaf1c",alt:"A woman walking slowly along a sunny path"}},{id:"meditation-5",practice:["Choose acceptable short wishes for yourself or a safe loved person; the wording is an ODA adaptation.","Offer wishes voluntarily, without requiring warmth; skip recipients or use an outward anchor if uncomfortable.","A difficult recipient is optional and never necessary. Stop if distressed; keep boundaries and avoid unsafe contact."],reflection:"To whom was it easiest, and to whom hardest, to direct your good wishes?",question:"What do you do if you feel no warm emotion during metta?",options:["I decide the method does not fit me and choose to stop.","I try to force the feeling to appear.","If it feels tolerable, I can continue voluntarily without requiring warm feelings."],correct:2,feedback:"Warmth is not required for a voluntary wish. Continuing through distress is not required either. You can change recipients, use outward attention or stop; wishes do not require forgiveness or contact.",photo:{id:"1604881991720-f91add269bed",alt:"Two people holding hands kindly across a table"}},{id:"meditation-6",practice:["Name a specific recurring cue, the thought that appears and the behavior you want to change.","Optionally write or imagine one feasible response in a safe scene; this is preparation, not personality change.","Choose the real response and its cue: “If this happens, then I will do this.” Record the real attempt separately."],reflection:"In the moment your old state switches on, what would the person you want to be do differently?",question:"Which part of this technique is best supported by research?",options:["Changing events and reality through the quantum field.","Rehearsing the behavior you want in your mind and then trying it in real life.","Healing illness with thought so that medication is no longer needed."],correct:1,feedback:"Research concerns small average task and skill performance benefits, not a new-self ritual or an established advantage from adding a real-life attempt. Keep care; quantum and healing claims are unsupported.",photo:{id:"1631832293782-2eda7804489b",alt:"A quiet room with morning sun streaming through the window and a potted plant in front of it"}},{id:"meditation-7",practice:["Choose a recognizable cue and safe place for a practice that fits your life.","Choose a tolerable short version and schedule its next opportunity; log later attempts only after they occur.","Write a feasible outward, seated or nonmovement backup, including stopping and support when needed."],reflection:"Which technique in this course helped you most, and why?",question:"If your distress clearly grows during meditation and old memories shake you, what should you do?",options:["I stop, open my eyes, feel my feet and get support from a professional.","I sit longer and wait for these feelings to pass on their own.","I take it as a sign the meditation is going well and keep pushing."],correct:0,feedback:"Difficult experiences can occur, but a pooled review percentage is not your brief-session risk. Stop if distress grows and seek qualified support for recurring concerns. Do not delay care or emergency help.",photo:{id:"1781255575628-d645cc39160f",alt:"A simple corner with colorful floor cushions and woven poufs on a wooden floor"}}],o={id:"meditation",title:"Mind keeps wandering? Return to what matters",subtitle:"Seven short lessons. Test a comfortable anchor, then use attention in a task or conversation.",description:"Build one voluntary attention experiment around a useful act in your own life. Try another anchor only when it addresses a real difficulty, review what happened and keep a workable version.",scope:"Meditation education for adults; it is not diagnosis or treatment and does not replace therapy or medication. Do not change prescribed care without your clinician. For trauma, psychosis or severe distress, plan with a qualified mental health professional; a teacher does not replace assessment. Keep eyes open, choose an outward anchor or pause when needed. Stop if distress, dizziness or detachment grows; seek support for persistent, recurring or concerning symptoms. Do not practice while driving. Seek medical assessment for new or persistent pain, numbness or other concerning symptoms. Self-harm thoughts warrant prompt professional or crisis support; immediate danger requires local emergency help.",outcome:"A chosen attention-and-action plan, honest attempt records, and a workable next week with clear stop and support routes.",photo:{id:"1522075782449-e45a34f1ddfb",alt:"A woman sitting quietly on a bench looking out over a mountain view"},lessons:a.map((e,t)=>({...n[t],schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:e.idea.paragraphs,example:e.idea.example,deeper:e.goDeeper.sections,sources:[...new Set([...e.goDeeper.sourceIds,"meditation-M03"])],takeaway:e.carry.takeaway,visual:{kind:"steps",title:"One continuing experiment",steps:[{label:"Cue",text:"Choose a workable opening."},{label:"Act",text:"Try the useful minimum."},{label:"Return",text:"Record and choose the next attempt."}]}}))};export{o as COURSE,a as MEDITATION_LESSONS_V2,i as SOURCES};
